/**
 * The twelve flags, as pictures.
 *
 * Cut out of the icon set the countries cast is matched to, one disc per
 * country. The circular edge is **anti-aliased** rather than cut on a pixel
 * boundary: a hard mask leaves a stair-stepped rim once the picture is scaled
 * down onto a ball, and a stair-stepped rim is exactly what makes a bitmap look
 * like a bitmap next to a drawn shape.
 *
 * They are carried as data rather than as files for two reasons: a static export
 * served under a path prefix has to be told that prefix for every asset it
 * fetches, and a fetch that fails leaves a video with holes in it where the
 * flags should be. Data cannot fail to arrive.
 *
 * The colour is quantised to forty-eight levels each, which flat artwork loses
 * nothing to and which keeps the set under ninety kilobytes.
 *
 * They are somebody else's artwork. That is worth knowing rather than
 * discovering: the drawn set this replaced owed nothing to anyone.
 */

export const FLAG_PNG: Record<string, string> = {
  us: 'data:image/png;base64,',
  cn: 'data:image/png;base64,',
  jp: 'data:image/png;base64,',
  de: 'data:image/png;base64,',
  in: 'data:image/png;base64,',
  gb: 'data:image/png;base64,',
  fr: 'data:image/png;base64,',
  it: 'data:image/png;base64,',
  ca: 'data:image/png;base64,',
  ru: 'data:image/png;base64,',
  es: 'data:image/png;base64,',
  mx: 'data:image/png;base64,',
};
